create table if not exists public.cash_forecast_lines (id uuid primary key default gen_random_uuid(), organization_id uuid not null, planning_version_id uuid not null, financial_period_id uuid not null, cash_category text not null check (cash_category in ('opening_cash','cash_inflow','cash_outflow','financing','closing_cash')), amount_minor bigint not null, currency char(3) not null default 'SAR', notes text, created_by uuid not null default auth.uid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(planning_version_id,financial_period_id,cash_category));
create index if not exists idx_cash_forecast_org_version on public.cash_forecast_lines(organization_id,planning_version_id);
create index if not exists idx_cash_forecast_period on public.cash_forecast_lines(financial_period_id);
alter table public.cash_forecast_lines enable row level security;
drop policy if exists cash_forecast_select on public.cash_forecast_lines;
create policy cash_forecast_select on public.cash_forecast_lines for select to authenticated using (public.has_org_permission(organization_id,'view'));
drop policy if exists cash_forecast_manage on public.cash_forecast_lines;
create policy cash_forecast_manage on public.cash_forecast_lines for all to authenticated using (public.has_org_permission(organization_id,'manage_budget')) with check (public.has_org_permission(organization_id,'manage_budget'));
create or replace function public.get_cash_forecast_workspace(p_organization_id uuid,p_planning_version_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_result jsonb; begin if auth.uid() is null or not public.has_org_permission(p_organization_id,'view') then raise exception 'forbidden'; end if; if not exists(select 1 from public.planning_versions where id=p_planning_version_id and organization_id=p_organization_id and version_type='forecast') then raise exception 'invalid forecast version'; end if; select jsonb_build_object('version',to_jsonb(v),'periods',coalesce((select jsonb_agg(to_jsonb(p) order by p.period_start) from public.financial_periods p where p.organization_id=p_organization_id),'[]'::jsonb),'lines',coalesce((select jsonb_agg(to_jsonb(c) order by c.financial_period_id,c.cash_category) from public.cash_forecast_lines c where c.organization_id=p_organization_id and c.planning_version_id=p_planning_version_id),'[]'::jsonb)) into v_result from public.planning_versions v where v.id=p_planning_version_id; return v_result; end; $$;
create or replace function public.upsert_cash_forecast_line(p_organization_id uuid,p_planning_version_id uuid,p_financial_period_id uuid,p_cash_category text,p_amount_minor bigint,p_currency char(3) default 'SAR',p_notes text default null) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; begin if auth.uid() is null or not public.has_org_permission(p_organization_id,'manage_budget') then raise exception 'forbidden'; end if; if not exists(select 1 from public.planning_versions where id=p_planning_version_id and organization_id=p_organization_id and version_type='forecast' and status='draft') then raise exception 'forecast must be draft'; end if; if not exists(select 1 from public.financial_periods where id=p_financial_period_id and organization_id=p_organization_id) then raise exception 'invalid period'; end if; if p_cash_category not in ('opening_cash','cash_inflow','cash_outflow','financing','closing_cash') then raise exception 'invalid cash category'; end if; insert into public.cash_forecast_lines(organization_id,planning_version_id,financial_period_id,cash_category,amount_minor,currency,notes,created_by) values(p_organization_id,p_planning_version_id,p_financial_period_id,p_cash_category,p_amount_minor,p_currency,p_notes,auth.uid()) on conflict(planning_version_id,financial_period_id,cash_category) do update set amount_minor=excluded.amount_minor,currency=excluded.currency,notes=excluded.notes,updated_at=now() returning id into v_id; return v_id; end; $$;
create or replace function public.delete_cash_forecast_line(p_organization_id uuid,p_cash_forecast_line_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null or not public.has_org_permission(p_organization_id,'manage_budget') then raise exception 'forbidden'; end if; delete from public.cash_forecast_lines c where c.id=p_cash_forecast_line_id and c.organization_id=p_organization_id and exists(select 1 from public.planning_versions v where v.id=c.planning_version_id and v.status='draft'); end; $$;
revoke all on public.cash_forecast_lines from public,anon;
grant select on public.cash_forecast_lines to authenticated;
revoke all on function public.get_cash_forecast_workspace(uuid,uuid),public.upsert_cash_forecast_line(uuid,uuid,uuid,text,bigint,char,text),public.delete_cash_forecast_line(uuid,uuid) from public,anon;
grant execute on function public.get_cash_forecast_workspace(uuid,uuid),public.upsert_cash_forecast_line(uuid,uuid,uuid,text,bigint,char,text) to authenticated;
